//! Independent immutable old registration, actual old Walker and semantic model.
use crate::lint::Registry;
#[path="../fixtures/original_policies/untyped_member_workspace.rs"]mod original;
#[path="../fixtures/native-untyped-member-workspace/fixture.rs"]mod fixture;
#[path="../../dmb/shared/test_scratch.rs"]mod scratch;
#[test]fn original_untyped_member_whole_reports_cover_statement_roots_shadow_return_fallback_maps_and_macros(){use sha1::Digest as _;assert_eq!(format!("{:x}",sha1::Sha1::digest(include_bytes!("../fixtures/original_policies/untyped_member_workspace.rs"))),"f4670169253c10841b059e396253f2ca533eb0ea");for case in fixture::CASES{let root=scratch::dir(&format!("old-untyped-member-{case}"));for(relative,bytes)in fixture::files(case){let target=root.join(relative);std::fs::create_dir_all(target.parent().unwrap()).unwrap();std::fs::write(target,bytes).unwrap();}let mut registry=Registry::default();original::register(&mut registry);let old=crate::run::Engine::new(registry,crate::run::Options{root:root.clone(),lints:vec!["untyped_member".into()],no_cache:true,raw:true,..Default::default()}).unwrap();let sem=crate::sem::sem_for(&old.tree).unwrap();assert!(sem.errors.is_empty(),"actual old parsing failed: {:?}",sem.errors);if *case=="noncode"{let mut map_body=false;for ty in sem.objtree.iter_types(){for(_,proc_type)in ty.get().procs.iter(){for body in proc_type.value.iter(){if body.code.is_some()&&sem.file_of(body.location)==Some("maps/member.dm"){map_body=true}}}}assert!(map_body,"the actual Original loader must compile the map procedure before the policy domain is tested");}if *case=="noncode"{assert!(original::static_names(&sem).contains("outside_static"),"the actual whole Original declaration universe must contain the map-only static name");}let outcome=old.run_one(old.reg.lints[0].as_ref());assert!(outcome.internal_error.is_none());if *case=="exempt"{assert!(outcome.run.sites.is_empty());}else{assert!(!outcome.run.sites.is_empty(),"genuine positive {case}");}if *case=="noncode"{assert!(outcome.run.sites.iter().any(|s|s.rel=="code/main.dm"),"whole old static universe includes map declarations");assert!(!outcome.run.sites.iter().any(|s|s.rel.starts_with("maps/")),"old body domain explicitly excludes map procs");}assert!(outcome.run.notes.is_empty()&&outcome.allow_used.is_empty());println!("ORIGINAL_UNTYPED_MEMBER_FULL={}",serde_json::json!({"case":case,"sites":outcome.run.sites,"notes":outcome.run.notes,"allow_used":outcome.allow_used,"failed":outcome.failed,"text":outcome.text}));}}
